-- VULNERABLE:
GET /api/v1/profile?user_id=1042      <- your own record, returns fine
GET /api/v1/profile?user_id=0001      <- someone else's record — server never checks ownership, returns it anyway

@app.route("/api/v1/profile")
def profile():
    user_id = request.args.get("user_id")
    return db.get_user(user_id)          # no check that user_id belongs to the requester

-- SECURE:
@app.route("/api/v1/profile")
def profile():
    user_id = request.args.get("user_id")
    if user_id != current_session.user_id and not current_session.is_admin:
        return "403 Forbidden", 403
    return db.get_user(user_id)

-- VULNERABLE:
GET /api/v1/view?file=report.pdf                       <- intended use
GET /api/v1/view?file=../../../../etc/aether/master_key.pem   <- escapes the web root entirely

def view(filename):
    return open(f"/var/www/reports/{filename}").read()   # no validation of the resolved path at all

-- SECURE:
import os
def view(filename):
    base = "/var/www/reports"
    full_path = os.path.realpath(os.path.join(base, filename))
    if not full_path.startswith(base):
        return "403 Forbidden", 403                        # resolved path escaped the base dir — reject it
    return open(full_path).read()
